"% model.m

% 1. Define Nominal System
V = 710.0;
Xu = -0.0066;
Xw = 0.039;
Zu = -0.032;
Zw = -0.72;
Mw = -0.0053;
Mq = -0.9;
g = 32.174;

A = [Xu, Xw, 0, -g;
     Zu, Zw, V, 0;
     0,  Mw, Mq, 0;
     0,  0,  1, 0];

B = [0; -6.0; -4.0; 0];

% 2. Design State Feedback Gain K
% Desired Short-Period Poles
wn_sp = 2.0;
zeta_sp = 0.6;
% Characteristic polynomial: s^2 + 2*zeta*wn*s + wn^2 = 0
p_sp = roots([1, 2*zeta_sp*wn_sp, wn_sp^2]);

% Identify Nominal Phugoid Poles (to be held at open-loop)
eig_ol = eig(A);
wn_ol = abs(eig_ol);
[~, idx_ol] = sort(wn_ol, 'ascend');
p_ph = eig_ol(idx_ol(1:2)); % Two lowest frequency poles are Phugoid

% Assemble target poles for placement
p_target = [p_sp; p_ph];

% Compute K
K = place(A, B, p_target);

% 3. Monte Carlo Simulation
N = 200;
pct = 0.25;

% Generate independent random multipliers with specific seeds
rng(20260827);
f_Mw = 1 + pct * (2 * rand(N, 1) - 1);

rng(20261827);
f_Zw = 1 + pct * (2 * rand(N, 1) - 1);

rng(20262827);
f_Mq = 1 + pct * (2 * rand(N, 1) - 1);

pass_count = 0;

for i = 1:N
    % Create perturbed A matrix
    A_i = A;

    % Apply perturbations
    % Mw is A(3,2), Zw is A(2,2), Mq is A(3,3)
    A_i(3,2) = A(3,2) * f_Mw(i);
    A_i(2,2) = A(2,2) * f_Zw(i);
    A_i(3,3) = A(3,3) * f_Mq(i);

    % Closed-loop eigenvalues
    ev = eig(A_i - B * K);

    % Identify Short-Period poles (highest natural frequency)
    wn_all = abs(ev);
    [wn_sorted, idx] = sort(wn_all, 'descend');

    % The two highest frequencies correspond to the short-period mode
    sp_eigs = ev(idx(1:2));

    % Calculate metrics
    wn_current = abs(sp_eigs);
    zeta_current = -real(sp_eigs) ./ wn_current;

    % Check specifications
    % Spec 1: 1.88 <= wn <= 2.12
    cond_wn = all(wn_current >= 1.88 & wn_current <= 2.12);

    % Spec 2: zeta >= 0.51
    cond_zeta = all(zeta_current >= 0.51);

    if cond_wn && cond_zeta
        pass_count = pass_count + 1;
    end
end

% 4. Write Results
result.pass_fraction = pass_count / N;
result.failing_case_count = N - pass_count;

fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(result));
fclose(fid);"
